# Noun morphology word = "child" print("Noun Morphology") print("----------------") print("Singular :", singularize(word)) print("Plural :", pluralize(word)) # Verb morphology verb = "play" print("\nVerb Morphology") print("----------------") print("Base :", verb) print("Past :", conjugate(verb, tense="past")) print("Present :", conjugate(verb, tense="present")) print("Participle:", conjugate(verb, tense="present", aspect="progressive")) 
